head.script:


            scwin.getType = function ( info ) {

                var rowIndex = info.rowIndex;
                var colIndex = info.colIndex;
                var returnInfo;




				if (dataList1.getCellData(rowIndex, "col2") == 1) {
					returnInfo = {
		                id : "dynamic_radioaaa_" + rowIndex + "_" + colIndex,
						inputType : "radio",
						options:{
							cellGroupName :"radioAPP",
							selectedIndex :"-1"
						}
					};

                } else if(dataList1.getCellData(rowIndex, "col2") == 2) {
					returnInfo = {
		               id : "dynamic_radio1bbb_" + rowIndex + "_" + colIndex,
						inputType : "radio",
						options:{
							cellGroupName :"radiobbb",
							selectedIndex : "-1"
						}
					};


                }else if(dataList1.getCellData(rowIndex, "col2") == 3) {
					returnInfo = {
		               id : "dynamic_radio1cc_" + rowIndex + "_" + colIndex,
						inputType : "radio",
						options:{
							cellGroupName :"radiocc",
							selectedIndex : "-1"
						}
					};


                }
                else {

					returnInfo = {
		               id : "dynamic_text" + rowIndex + "_" + colIndex,
						inputType : "text",
						options:{

						}
					};


				}


                return returnInfo;

			};


	scwin.grd_onviewchange = function(info) {
		//grd.refreshRow(info.rowIndex);

	};

	scwin.onpageload = function() {
		var jsonData = [{ "col2":"1"},{"col2":"1"},{ "col2":"2"},{ "col2":"2"},{ "col2":"2"},{ "col2":"2"},{"col2":"3"},{ "col2":"3"},{ "col2":"4"}];
	    dataList1.setJSON( jsonData );



	};

	scwin.onpageunload = function() {

	};

scwin.dataList1_oncelldatachange = function(info) {
console.log('oncelldatachange',info);
};

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('grd_cell_0_0').children[0].checked;
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('grd_cell_2_0').children[0].checked;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_cell_0_0').children[0].click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_cell_2_0').children[0].click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_cell_6_0').children[0].click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");				
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
